const MAX_REVIEW_ROUNDS=3;
const submitted=$input.item.json;
const original=$('Execute Workflow: Scouting Brief erstellen').first().json;
const reviewDecision=(submitted['Entscheidung']||'').toString().trim();
const reviewFeedback=(submitted['Feedback (Pflicht bei Request Changes)']||'').toString().trim();
const errors=[];
if(!['Approve','Request Changes','Reject'].includes(reviewDecision)) errors.push('Unbekannte Review-Entscheidung: '+reviewDecision);
if(reviewDecision==='Request Changes'&&!reviewFeedback) errors.push('Fuer \"Request Changes\" ist ein Feedback-Text erforderlich.');

const problem=(submitted['Hauptproblem (Diagnose)']||'').toString().trim();
const targetPosition=(submitted['Zielposition']||'').toString().trim();
const role=(submitted['Rolle']||'').toString().trim();
const reasoning=(submitted['Begruendung']||'').toString().trim();
if(!problem) errors.push('Feld \"Hauptproblem (Diagnose)\" darf nicht leer sein.');
if(!targetPosition) errors.push('Feld \"Zielposition\" darf nicht leer sein.');
if(!role) errors.push('Feld \"Rolle\" darf nicht leer sein.');
if(!reasoning) errors.push('Feld \"Begruendung\" darf nicht leer sein.');

function parseJsonArrayField(label){
  const raw=(submitted[label]||'').toString().trim();
  try{
    const parsed=JSON.parse(raw);
    if(!Array.isArray(parsed)) throw new Error('kein Array');
    return parsed;
  }catch(e){
    errors.push('Feld \"'+label+'\" enthaelt kein gueltiges JSON-Array: '+e.message);
    return undefined;
  }
}
const weightedCriteria=parseJsonArrayField('Gewichtete Kriterien (JSON-Array)');
const constraints=parseJsonArrayField('Constraints (JSON-Array)');
const uncertainties=parseJsonArrayField('Unsicherheiten (JSON-Array)');

const ALLOWED_CRITERIA=new Set(['goals','assists','appearances','age','minutesPlayed']);
if(Array.isArray(weightedCriteria)){
  if(weightedCriteria.length===0){
    errors.push('Feld \"Gewichtete Kriterien (JSON-Array)\" darf nicht leer sein.');
  } else {
    weightedCriteria.forEach((criterion,index)=>{
      if(!criterion||typeof criterion!=='object'||Array.isArray(criterion)){
        errors.push(`Gewichtete Kriterien[${index}] muss ein Objekt sein.`);
        return;
      }
      if(!ALLOWED_CRITERIA.has(criterion.criterion)){
        errors.push(`Gewichtete Kriterien[${index}].criterion ist ungueltig: ${criterion.criterion}. Erlaubt sind ${[...ALLOWED_CRITERIA].join(', ')}.`);
      }
      if(typeof criterion.weight!=='number'||!Number.isFinite(criterion.weight)||criterion.weight<0||criterion.weight>1){
        errors.push(`Gewichtete Kriterien[${index}].weight muss eine endliche Zahl zwischen 0 und 1 sein.`);
      }
    });
  }
}
if(Array.isArray(uncertainties) && uncertainties.some((entry)=>typeof entry!=='string')){
  errors.push('Feld \"Unsicherheiten (JSON-Array)\" darf nur Strings enthalten.');
}

if(Array.isArray(constraints)){
  constraints.forEach((constraint,index)=>{
    if(!constraint||typeof constraint!=='object'||Array.isArray(constraint)){
      errors.push(`Constraints[${index}] muss ein Objekt sein.`);
      return;
    }
    if(!['age','marketValueMEUR'].includes(constraint.field)){
      errors.push(`Constraints[${index}].field ist ungueltig: ${constraint.field}. Erlaubt sind age, marketValueMEUR.`);
    }
    if(!['max','min'].includes(constraint.operator)){
      errors.push(`Constraints[${index}].operator ist ungueltig: ${constraint.operator}. Erlaubt sind max, min.`);
    }
    if(typeof constraint.value!=='number'||!Number.isFinite(constraint.value)){
      errors.push(`Constraints[${index}].value muss eine endliche Zahl sein.`);
    }
  });
}

const reviewRound=(original.scoutingBrief&&original.scoutingBrief.reviewRound)||1;
const maxRoundsReached=reviewDecision==='Request Changes'&&reviewRound>=MAX_REVIEW_ROUNDS;
if(maxRoundsReached){
  errors.push(`Die maximale Anzahl von ${MAX_REVIEW_ROUNDS} Review-Runden ist erreicht. Bitte waehlen Sie explizit Approve oder Reject.`);
}
const reviewOutcome=reviewDecision;
const valid=errors.length===0;
const scoutingBrief=valid?{...original.scoutingBrief,problem,targetPosition,role,reasoning,weightedCriteria,constraints,uncertainties}:original.scoutingBrief;

// Der freigegebene Formularstand ist die einzige massgebliche Quelle.
// playerProfile wird synchronisiert, weil die Kandidatensuche dieses Objekt
// bevorzugt. teamDiagnosis wird fuer die beiden ebenfalls editierbaren
// Diagnosefelder synchronisiert, weil sowohl die finale Ergebnisdarstellung
// (Approve) als auch die naechste Scouting-Brief-Runde (Request Changes)
// mainProblem/uncertainties aus teamDiagnosis lesen. Ohne diese Synchronisierung
// wuerden genau diese Reviewer-Edits spaeter wieder durch die urspruenglichen
// KI-Werte ersetzt.
const playerProfile=valid?{...original.playerProfile,position:targetPosition,role,reasoning,weightedCriteria,constraints}:original.playerProfile;
const teamDiagnosis=valid?{...(original.teamDiagnosis||{}),mainProblem:problem,uncertainties}:original.teamDiagnosis;
return [{json:{...original,scoutingBrief,playerProfile,teamDiagnosis,reviewDecision,reviewFeedback,reviewOutcome,maxRoundsReached,valid,errorMessage:valid?undefined:'Die Review-Entscheidung ist ungueltig.\n\n'+errors.join('\n')}}];

const item=$input.item.json;
const reason=item.maxRoundsReached?`Die maximale Anzahl von ${item.scoutingBrief.maxReviewRounds} Ueberarbeitungsrunden fuer das Scouting Brief ist erreicht worden.`:'Der Sporting Director hat das Scouting Brief abgelehnt (Reject).';
const feedback=item.reviewFeedback?`

Feedback: ${item.reviewFeedback}`:'';
return [{json:{...item,errorMessage:`Die Kandidatensuche wurde nach der Human-Review kontrolliert beendet.

${reason}${feedback}`}}];

const item=$input.item.json||{};
const rawError=item.error;
const errorMessage=typeof rawError==='string'?rawError:(rawError&&rawError.message)?rawError.message:(item.errorMessage||'Es ist ein unbekannter Capability-Fehler aufgetreten.');
return [{json:{...item,errorMessage}}];
